<script>(()=>{const nav=document.getElementById('mobile-nav'),left=document.getElementById('mobile-nav-left'),right=document.getElementById('mobile-nav-right');if(!nav||!left||!right)return;const update=()=>{const max=Math.max(0,nav.scrollWidth-nav.clientWidth),pos=nav.scrollLeft;left.classList.toggle('is-available',pos>3);right.classList.toggle('is-available',pos<max-3)};const scroll=d=>nav.scrollBy({left:d*Math.max(180,Math.min(260,nav.clientWidth*.72)),behavior:'smooth'});const revealActive=()=>{const active=nav.querySelector('a.active');if(!active)return;const target=Math.max(0,Math.min(active.offsetLeft-(nav.clientWidth-active.offsetWidth)/2,nav.scrollWidth-nav.clientWidth));nav.scrollTo({left:target,behavior:'instant'});update()};left.addEventListener('click',()=>left.classList.contains('is-available')&&scroll(-1));right.addEventListener('click',()=>right.classList.contains('is-available')&&scroll(1));nav.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',()=>{update();revealActive()});if('ResizeObserver'in window)new ResizeObserver(()=>{update();revealActive()}).observe(nav);requestAnimationFrame(()=>{update();requestAnimationFrame(revealActive)})})();</script>
